// This file is auto-generated. Do not edit it manually.
export const hamletPartials = {
  "hamlet.defaultmarkups": "{{!-- Clean all inclusions of all widgets automatically  --}}\r\n{{#each defaultmarkups}}\r\n<b:defaultmarkup type='{{@key}}'>\r\n  {{#each this}}\r\n  <b:includable id='{{this}}'/>\r\n  {{/each}}\r\n</b:defaultmarkup>\r\n{{/each}}\n",
  "hamlet.snippet": "{{!--\r\nCreates a clean text snippet of a string with conditional ellipsis support.\r\n@author zkreations\r\n@param {String} [text=\"\"] - Text or HTML content to be shortened\r\n@param {String} [tag=\"p\"] - Container HTML tag name\r\n@param {String} [id] - Container HTML id\r\n@param {String} [class] - Container CSS class\r\n@param {Number} [limit=70] - Maximum length of the string\r\n@param {String} [ellipsis=\"...\"] - Ellipsis to be added only if the text is truncated\r\n--}}\r\n<b:includable id='@snippet'>\r\n  <b:with value='data:text ? (data:text snippet {\r\n    links: false,\r\n    ellipsis: false,\r\n    linebreaks: false\r\n  }) : \"\"' var='cleanString'>\r\n    <b:if cond='data:cleanString != \"\"'>\r\n      {{!-- Ensure the limit is a number and set a default if not provided --}}\r\n      <b:with value='(data:limit + 0) == data:limit ? (data:limit * 1) : 70' var='maxLength'>\r\n        <b:tag expr:name='data:tag ?: \"p\"'>\r\n          <b:class cond='data:class' expr:name='data:class'/>\r\n          <b:attr name='id' expr:value='data:id'/>\r\n          {{!-- Truncate the clean string to the specified maximum length and append ellipsis if necessary --}}\r\n          <b:with value='data:cleanString snippet {\r\n            length: data:maxLength,\r\n            links: false,\r\n            ellipsis: false,\r\n            linebreaks: false\r\n          }' var='truncatedText'>\r\n            {{!-- Render the truncated text and conditionally add ellipsis if the original string exceeds the maximum length --}}\r\n            <b:eval expr='data:truncatedText + (\r\n              data:cleanString.size > data:maxLength ? (data:ellipsis ?: \"...\") : \"\"\r\n            )'/>\r\n          </b:with>\r\n        </b:tag>\r\n      </b:with>\r\n    <b:else/>\r\n      <b:comment render='true'>No visible text to display after sanitization.</b:comment>\r\n    </b:if>\r\n  </b:with>\r\n</b:includable>\n",
  "hamlet.picture": "{{!--\r\nCreate a responsive custom picture tag using native Blogger image sizing.\r\n@author zkreations\r\n@param {image} src - Image URL or Blogger image object\r\n@param {number[]} [sourceSet=[700,400]] - Array of widths for the responsive sources\r\n@param {Number} [width] - Explicit image width for the fallback img\r\n@param {Number} [height] - Explicit image height for the fallback img\r\n@param {String} [ratio] - Aspect ratio (e.g., \"16:9\", \"1:1\")\r\n@param {String} [id] - Unique identifier for the img tag\r\n@param {String} [class] - Additional CSS classes for the img tag\r\n@param {String} [imgClass] - CSS classes for the fallback img tag\r\n@param {string} [sizes] - Sizes attribute\r\n@param {string} [loading] - Loading attribute\r\n@param {string} [fetchpriority] - Fetch priority attribute\r\n@param {string} [crossorigin] - Cross-origin attribute\r\n@param {string} [decoding] - Decoding attribute\r\n@param {string} [referrerpolicy] - Referrer policy attribute\r\n@param {string} [alt] - Alt text\r\n@param {string} [params] - Additional parameters for proxy images\r\n--}}\r\n<b:includable id='@picture'>\r\n  <b:if cond='data:src'>\r\n    <picture>\r\n      <b:class cond='data:class' expr:name='data:class'/>\r\n      <b:with value='data:src.isYoutube\r\n        ? data:src.youtubeMaxResDefaultUrl\r\n        : data:src' var='baseImage'>\r\n        <b:with value='data:sourceSet ?: [700, 400]' var='availableSizes'>\r\n          {{!-- Check if the image is from a proxy server and append parameters if necessary --}}\r\n          <b:with value='[\r\n            \"com/img/a/\",\r\n            \"com/blogger_img_proxy\"\r\n          ] any (server => server in data:baseImage)' var='isProxyImg'>\r\n            <b:with value='data:params and data:isProxyImg ? (\"-\" + data:params) : \"\"' var='params'>\r\n              {{!-- Generate <source> tags for each size in the sourceSet array --}}\r\n              <b:loop index='i' values='data:availableSizes' var='size'>\r\n                <b:if cond='data:i + 1 != data:availableSizes.length'>\r\n                  <b:with value='resizeImage(data:baseImage, data:size, data:ratio)' var='sourceUrl'>\r\n                    <source expr:media='\"(min-width: \" + data:size + \"px)\"' expr:srcset='data:sourceUrl + data:params'/>\r\n                  </b:with>\r\n                </b:if>\r\n              </b:loop>\r\n              {{!-- Fallback <img> tag for the last size in the sourceSet array --}}\r\n              <b:with value='data:availableSizes.last ?: 600' var='fallbackSize'>\r\n                <b:with value='resizeImage(data:baseImage, data:fallbackSize, data:data:ratio)' var='fallbackUrl'>\r\n                  <b:tag name='img'>\r\n                    <b:attr name='b:whitespace' value='remove'/>\r\n                    <b:class cond='data:imgClass' expr:name='data:imgClass'/>\r\n                    {{!-- Add data attributes for each of the specified attributes if they exist --}}\r\n                    <b:loop values='[\"id\",\"sizes\",\"loading\",\"fetchpriority\",\"crossorigin\",\"decoding\",\"referrerpolicy\",\"alt\"]' var='attr'>\r\n                      <b:with expr:value='+(\"data:\",data:attr)' var='value'>\r\n                        <b:attr expr:name='data:attr' expr:value='data:value'/>\r\n                      </b:with>\r\n                    </b:loop>\r\n                    <b:attr name='width' expr:value='data:width ?: data:fallbackUrl.width'/>\r\n                    <b:attr name='height' expr:value='data:height ?: data:fallbackUrl.height'/>\r\n                    <b:attr name='src' expr:value='data:fallbackUrl + data:params'/>\r\n                  </b:tag>\r\n                </b:with>\r\n              </b:with>\r\n            </b:with>\r\n          </b:with>\r\n        </b:with>\r\n      </b:with>\r\n    </picture>\r\n  <b:else/>\r\n    <b:comment render='true'>Parameter [src] is required.</b:comment>\r\n  </b:if>\r\n</b:includable>\n",
  "hamlet.meta": "{{!--\r\nGenerates essential metadata, SEO, and Open Graph/Twitter Cards.\r\n@author zkreations\r\n@param {String} [icon] - Base URL to generate responsive favicons.\r\n@param {Array[Number]} [iconSizes=[32,96,180,192]] - Dimensions for the favicons.\r\n@param {String} [robots] - Custom meta robots configuration for homepage/posts.\r\n@param {String} [defaultImage] - Default image URL for social networks.\r\n@param {String} [twitterCard=\"summary_large_image\"] - Twitter Card type (summary, summary_large_image).\r\n@param {String} [twitterSite] - Twitter/X handle of the website (e.g., @zkreations).\r\n--}}\r\n<b:includable id='@meta'>\r\n  {{!-- Common Meta Tags --}}\r\n  <meta expr:charset='data:blog.encoding'/>\r\n  <meta content='width=device-width,initial-scale=1' name='viewport'/>\r\n  {{!-- Favicon / Icons --}}\r\n  <b:if cond='data:icon'>\r\n    <b:loop values='data:iconSizes ?: [32,96,180,192]' var='size'>\r\n      <link expr:href='resizeImage(data:icon, data:size, \"1:1\")' rel='icon' expr:sizes='data:size + \"x\" + data:size' type='image/png'/>\r\n    </b:loop>\r\n  <b:else/>\r\n    <link expr:href='data:blog.blogspotFaviconUrl' rel='icon' type='image/x-icon'/>\r\n  </b:if>\r\n  {{!-- Description (Only if exists to avoid empty meta tags) --}}\r\n  <b:if cond='data:view.description'>\r\n    <meta expr:content='data:view.description.escaped' name='description'/>\r\n    <meta expr:content='data:view.description.escaped' property='og:description'/>\r\n    <meta expr:content='data:view.description.escaped' name='twitter:description'/>\r\n  </b:if>\r\n  {{!-- Canonical URL & Titles --}}\r\n  <link expr:href='data:view.url.canonical' rel='canonical'/>\r\n  <meta expr:content='data:view.url.canonical' property='og:url'/>\r\n  <meta expr:content='data:view.url.canonical' name='twitter:url'/>\r\n  <meta expr:content='data:view.title.escaped' property='og:title'/>\r\n  {{!-- Robots --}}\r\n  <meta expr:content='data:view.isHomepage or data:view.isSingleItem\r\n    ? (data:robots ?: \"index,follow,max-snippet:-1,max-image-preview:large,max-video-preview:-1\")\r\n    : \"noindex,follow\"' name='robots'/>\r\n  {{!-- Open Graph Type --}}\r\n  <meta expr:content='data:view.isSingleItem ? \"article\" : \"website\"' property='og:type'/>\r\n  {{!-- Intelligent Handling of Social Media Images --}}\r\n  <b:with value='data:view.featuredImage ? data:view.featuredImage : (data:defaultImage ? data:defaultImage : false)' var='rawImage'>\r\n    <b:if cond='data:rawImage'>\r\n      <b:if cond='data:rawImage.isResizable'>\r\n        <meta expr:content='resizeImage(data:rawImage, 1200, \"1200:630\")' property='og:image'/>\r\n        <meta expr:content='resizeImage(data:rawImage, 1200, \"1200:630\")' name='twitter:image'/>\r\n        <meta content='1200' property='og:image:width'/>\r\n        <meta content='630' property='og:image:height'/>\r\n      <b:else/>\r\n        <meta expr:content='data:rawImage' property='og:image'/>\r\n        <meta expr:content='data:rawImage' name='twitter:image'/>\r\n      </b:if>\r\n    </b:if>\r\n  </b:with>\r\n  {{!-- Twitter Card --}}\r\n  <meta expr:content='data:twitterCard ?: \"summary_large_image\"' name='twitter:card'/>\r\n  <b:if cond='data:twitterSite'>\r\n    <meta expr:content='data:twitterSite' name='twitter:site'/>\r\n  </b:if>\r\n</b:includable>\n",
  "hamlet.menu": "{{!--\r\nCreate a menu from a list of links\r\n@author zkreations\r\n@param {array} links - Array of links\r\n@param {string} [prefix=\"__\"] - Prefix for filter links\r\n@param {string} [id] - Id for the menu\r\n@param {string} [class] - Class for the menu\r\n@param {String} [itemClass] - Base class for the items (li)\r\n@param {String} [subnavClass] - Class for the nested submenus (ul)\r\n@param {String} [linkClass] - Base class for the anchors (a)\r\n@param {String} [hereClass] - State class when the link matches the current URL\r\n@param {String} [externalClass] - State class for external references\r\n--}}\r\n<b:includable id='@menu'>\r\n  <b:with value='data:prefix ?: \"__\"' var='prefix'>\r\n    <b:if cond='data:links[0].title contains data:prefix'>\r\n      <b:comment render='true'>The first element can't have the prefix</b:comment>\r\n    <b:elseif cond='data:links any (l => l.title + 0 == l.title)'/>\r\n      <b:comment render='true'>The element can't be a number</b:comment>\r\n    <b:elseif cond='!data:links.any'/>\r\n      <b:comment render='true'>The array can't be empty</b:comment>\r\n    <b:else/>\r\n      <ul class='nav'>\r\n        <b:class cond='data:class' expr:name='data:class'/>\r\n        <b:attr name='id' expr:value='data:id'/>\r\n        <b:loop index='i' values='data:links' var='link'>\r\n          {{!-- Check if the current or the next element contains the prefix --}}\r\n          <b:with value='{\r\n            current: (data:link.title contains data:prefix),\r\n            next: (data:links[data:i + 1].title contains data:prefix)\r\n          }' var='state'>\r\n            {{!-- Check if the menu has started or ended --}}\r\n            <b:with value='{\r\n              start: (data:state.next and !data:state.current),\r\n              end: (!data:state.next and data:state.current)\r\n            }' var='menu'>\r\n              <b:eval expr='\"&lt;li class=\\\"nav-item \" + (data:menu.start ? \"has-subnav \" : \"\") + data:itemClass + \"\\\">\"'/>\r\n              <a class='nav-link' expr:href='data:link.href'>\r\n                <b:class cond='data:linkClass' expr:name='data:linkClass'/>\r\n                {{!-- If the link is the current page or matches the canonical URL --}}\r\n                <b:if cond='data:link.isCurrentPage or data:view.url.canonical == data:link.href'>\r\n                  <b:class name='is-here'/>\r\n                  <b:class cond='data:hereClass' expr:name='data:hereClass'/>\r\n                </b:if>\r\n                {{!-- If the link is an external link --}}\r\n                <b:if cond='data:link.href contains \"?ref=\"'>\r\n                  <b:class name='is-external'/>\r\n                  <b:class cond='data:externalClass' expr:name='data:externalClass'/>\r\n                  <b:attr name='target' value='_blank'/>\r\n                  <b:attr name='rel' value='noopener noreferrer'/>\r\n                </b:if>\r\n                <data:link.title/>\r\n              </a>\r\n              <b:eval expr='data:menu.end ? \"&lt;/li>&lt;/ul>\" : \"\"'/>\r\n              <b:eval expr='data:menu.start ? \"&lt;ul class=\\\"nav-subnav \" + data:subnavClass + \" \\\">\" : \"&lt;/li>\"'/>\r\n            </b:with>\r\n          </b:with>\r\n        </b:loop>\r\n      </ul>\r\n    </b:if>\r\n  </b:with>\r\n</b:includable>\n",
  "hamlet.kind": "{{!--\r\nadd classes to body tag based on the current view\r\n@author zkreations\r\n@param {boolean} [viewId=true] - Add class based on ID (e.g. postId, pageId)\r\n--}}\r\n<b:includable id='@kind'>\r\n  <b:class cond='data:view.isHomepage' name='is-home'/>\r\n  <b:class cond='data:view.isMultipleItems' name='is-items'/>\r\n  <b:class cond='data:view.isPost' name='is-post'/>\r\n  <b:class cond='data:view.isPage' name='is-page'/>\r\n  <b:class cond='data:view.isArchive' name='is-archive'/>\r\n  <b:class cond='data:view.isLabelSearch' name='is-label'/>\r\n  <b:class cond='data:view.isSearch' name='is-search'/>\r\n  <b:class cond='data:view.isError' name='is-error'/>\r\n  <b:class cond='data:view.isPreview' name='is-preview'/>\r\n  {{!-- add class based on the current post/page id --}}\r\n  <b:if cond='data:view.isSingleItem'>\r\n    <b:class name='is-single'/>\r\n    <b:class cond='data:viewId != false' expr:name='\"single-id-\" + (data:view.postId ?: data:view.pageId)'/>\r\n  </b:if>\r\n</b:includable>\n",
  "hamlet.image": "{{!--\r\nCreate an image tag with optional attributes and responsive support\r\n@author zkreations\r\n@param {image} src - Image URL\r\n@param {number[]} [sourceSet] - Array of image widths (e.g. [320, 640, 1024])\r\n@param {number} [width] - Image width\r\n@param {number} [height] - Image height\r\n@param {number} [resize] - Change dimensions\r\n@param {string} [ratio] - Aspect ratio\r\n@param {string} [id] - Image ID\r\n@param {string} [class] - Additional classes\r\n@param {string} [sizes] - Sizes attribute\r\n@param {string} [loading] - Loading attribute\r\n@param {string} [fetchpriority] - Fetch priority attribute\r\n@param {string} [crossorigin] - Cross-origin attribute\r\n@param {string} [decoding] - Decoding attribute\r\n@param {string} [referrerpolicy] - Referrer policy attribute\r\n@param {string} [alt] - Alt text\r\n@param {string} [params] - Additional parameters for proxy images\r\n--}}\r\n<b:includable id='@image'>\r\n  <b:if cond='data:src'>\r\n    <b:with value='data:src.isYoutube\r\n      ? data:src.youtubeMaxResDefaultUrl\r\n      : data:src' var='baseImage'>\r\n      <b:with value='(data:resize\r\n        ? resizeImage(data:baseImage, data:resize, data:ratio)\r\n        : data:baseImage\r\n      )' var='image'>\r\n        <b:tag name='img'>\r\n          <b:attr name='b:whitespace' value='remove'/>\r\n          <b:class cond='data:class' expr:name='data:class'/>\r\n          {{!-- Add data attributes for each of the specified attributes if they exist --}}\r\n          <b:loop values='[\"id\",\"sizes\",\"loading\",\"fetchpriority\",\"crossorigin\",\"decoding\",\"referrerpolicy\",\"alt\"]' var='attr'>\r\n            <b:with expr:value='+(\"data:\",data:attr)' var='value'>\r\n              <b:attr expr:name='data:attr' expr:value='data:value'/>\r\n            </b:with>\r\n          </b:loop>\r\n          {{!-- Check if the image is from a proxy server and append parameters if necessary --}}\r\n          <b:with value='[\r\n            \"com/img/a/\",\r\n            \"com/blogger_img_proxy\"\r\n          ] any (server => server in data:image)' var='isProxyImg'>\r\n            <b:with value='data:params and data:isProxyImg ? (\"-\" + data:params) : \"\"' var='params'>\r\n              <b:with value='data:sourceSet ? resizeImage(data:image, data:sourceSet.first, data:ratio) : data:image' var='image'>\r\n                <b:attr name='src' expr:value='data:image + data:params'/>\r\n                <b:attr name='width' expr:value='data:width ?: data:image.width'/>\r\n                <b:attr name='height' expr:value='data:height ?: data:image.height'/>\r\n              </b:with>\r\n            </b:with>\r\n          </b:with>\r\n          {{!-- If sourceSet is provided, generate the srcset attribute --}}\r\n          <b:if cond='data:sourceSet'>\r\n            <b:attr name='srcset' expr:value='sourceSet(data:image, data:sourceSet, data:ratio)'/>\r\n          </b:if>\r\n        </b:tag>\r\n      </b:with>\r\n    </b:with>\r\n  <b:else/>\r\n    <b:comment render='true'>Parameter [src] is required.</b:comment>\r\n  </b:if>\r\n</b:includable>\n",
  "hamlet.contrast": "{{!--\r\nEvaluates a color's brightness and exposes its contrast state.\r\n@author zkreations\r\n@param {Color} color - Color variable from data:skin.vars\r\n@param {Number} [threshold=155] - Brightness limit to trigger the dark state (0-255)\r\n@param {String} [attr=\"data-theme\"] - Target attribute name to render\r\n--}}\r\n<b:includable id='@contrast'>\r\n  <b:with value='+((data:color.red * 0.299), (data:color.green * 0.587), (data:color.blue * 0.114))' var='brightness'>\r\n    <b:with value='(data:threshold + 0) == data:threshold ? (data:threshold * 1) : 155' var='limit'>\r\n      <b:attr expr:name='data:attr ?: \"data-theme\"' expr:value='data:brightness lt data:limit\r\n        ? \"dark\"\r\n        : \"light\"'/>\r\n    </b:with>\r\n  </b:with>\r\n</b:includable>\n",
  "hamlet.avatar": "{{!--\r\nCreate an avatar image with optional default image\r\n@author zkreations\r\n@param {image} src - Image URL\r\n@param {image} [default] - Default image URL\r\n@param {number} [width] - Image width\r\n@param {number} [height] - Image height\r\n@param {number} [resize=40] - Change dimensions\r\n@param {string} [id] - Image ID\r\n@param {string} [class] - Additional classes\r\n@param {string} [sizes] - Sizes attribute\r\n@param {string} [loading] - Loading attribute\r\n@param {string} [fetchpriority] - Fetch priority attribute\r\n@param {string} [crossorigin] - Cross-origin attribute\r\n@param {string} [decoding] - Decoding attribute\r\n@param {string} [referrerpolicy] - Referrer policy attribute\r\n@param {string} [alt] - Alt text\r\n--}}\r\n<b:includable id='@avatar'>\r\n  <b:if cond='data:src'>\r\n    <b:with value='data:default ?: \"https://lh3.googleusercontent.com/a/default-user\"' var='default'>\r\n      <b:with value='resizeImage((data:src contains \"/img/bl\" ? data:default : data:src), (data:resize ?: 40), \"1:1\")' var='image'>\r\n        <b:tag name='img'>\r\n          <b:attr name='b:whitespace' value='remove'/>\r\n          <b:class cond='data:class' expr:name='data:class'/>\r\n          {{!-- Add data attributes for each of the specified attributes if they exist --}}\r\n          <b:loop values='[\"id\",\"sizes\",\"loading\",\"fetchpriority\",\"crossorigin\",\"decoding\",\"referrerpolicy\",\"alt\"]' var='attr'>\r\n            <b:with expr:value='+(\"data:\",data:attr)' var='value'>\r\n              <b:attr expr:name='data:attr' expr:value='data:value'/>\r\n            </b:with>\r\n          </b:loop>\r\n          {{!-- Add the src, width, and height attributes --}}\r\n          <b:attr name='src' expr:value='data:image'/>\r\n          <b:attr name='width' expr:value='data:image.width'/>\r\n          <b:attr name='height' expr:value='data:image.height'/>\r\n        </b:tag>\r\n      </b:with>\r\n    </b:with>\r\n  <b:else/>\r\n    <b:comment render='true'>Parameter [src] is required.</b:comment>\r\n  </b:if>\r\n</b:includable>\n",
  "hamlet.attr": "{{!--\r\nAdd or remove multiple attributes\r\n@author zkreations\r\n@param {Array[Array]} data - Array of attribute name-value pairs\r\n--}}\r\n<b:includable id='@attr'>\r\n  <b:if cond='data:'>\r\n    <b:loop values='data:' var='i'>\r\n      <b:attr expr:name='data:i[0]' expr:value='data:i[1]'/>\r\n    </b:loop>\r\n  <b:else/>\r\n    <b:comment render='true'>Parameter [data] is required.</b:comment>\r\n  </b:if>\r\n</b:includable>\n",
  "hamlet.adsense": "{{!--\r\nAdSense async script\r\n@author zkreations\r\n--}}\r\n<b:includable id='@adsense'>\r\n  <b:if cond='data:blog.adsenseHostId and not data:blog.adsenseAutoAds'>\r\n    <b:tag async='async' name='script' cond='data:blog.adsenseClientId and data:blog.adsenseHasAds' expr:src='\"//pagead2.googlesyndication.com/pagead/js/adsbygoogle.js\" params {client: data:blog.adsenseClientId}' crossorigin='anonymous'/>\r\n  </b:if>\r\n</b:includable>\n",
  "hamlet.ads": "{{!--\r\nCreate adsense ads\r\n@author zkreations\r\n@param {string} [adClientId=data:blog.adsenseClientId] - Adsense client ID\r\n@param {string} [style=\"display: block\"] - Inline style\r\n@param {string} [slot] - ID of ad slot created in Adsense\r\n@param {string} [layout] - ID of layout (in-feed & in-article ads)\r\n--}}\r\n<b:includable id='@ads'>\r\n  <b:tag class='adsbygoogle' name='ins' data-full-width-responsive='true'>\r\n    <b:attr name='data-ad-client' expr:value='data:adClientId ?: data:blog.adsenseClientId'/>\r\n    <b:attr name='data-ad-host' expr:value='data:blog.adsenseHostId'/>\r\n    <b:attr name='data-ad-slot' expr:value='data:slot'/>\r\n    <b:attr name='data-ad-format' expr:value='data:layout ? \"fluid\" : \"auto\"'/>\r\n    <b:attr expr:name='\"data-ad-layout\" + (data:layout != \"in-article\" ? \"-key\" : \"\")' expr:value='data:layout'/>\r\n    <b:attr name='style' expr:value='data:style ?: \"display: block\"'/>\r\n  </b:tag>\r\n  <script>(adsbygoogle = window.adsbygoogle || []).push({})</script>\r\n</b:includable>\n",
  "hamlet.overrides": "{{> hamlet.defaultmarkups}}\n",
  "hamlet.functions": "{{> hamlet.adsense}}\n{{> hamlet.ads}}\n{{> hamlet.attr}}\n{{> hamlet.avatar}}\n{{> hamlet.contrast}}\n{{> hamlet.image}}\n{{> hamlet.kind}}\n{{> hamlet.menu}}\n{{> hamlet.meta}}\n{{> hamlet.picture}}\n{{> hamlet.snippet}}\n"
}
